// ECF Setup: Registering a Signal Handler
void signal_handler(int sig) {
    /* ECF triggered: kernel interrupts user code execution */
}
struct sigaction sa;
sa.sa_handler = signal_handler;
sa.sa_flags = 0; // Important: Prevents automatic syscall restart (SA_RESTART)
sigaction(SIGINT, &sa, NULL);

// Syscall Interaction: Handling Interruption
ssize_t ret;
char buffer[1024];

do {
    // Syscall (e.g., read, write, sleep)
    ret = read(fd, buffer, 1024);
} while (ret == -1 && errno == EINTR);
// EINTR (Error Interrupted): Syscall aborted by ECF (signal)
// Must manually restart the syscall if needed
if (ret != -1) { /* success */ }
